-- Some kudos + comments between test users (only if supabase-social-v2.sql has been run)
do $$ begin
  if to_regclass('public.kudos') is not null then
    insert into public.kudos (activity_user_id, activity_id, user_id)
    select p.user_id, p.activity_id, f.follower_id from public.activity_public p
    join public.follows f on f.followee_id = p.user_id
    where p.activity_id like 'seed_%_0' and f.follower_id::text like 'a0000000-%'
    on conflict do nothing;
  end if;
  if to_regclass('public.comments') is not null then
    insert into public.comments (activity_user_id, activity_id, user_id, body)
    select p.user_id, p.activity_id, f.follower_id, 'Looks great! 🙌' from public.activity_public p
    join public.follows f on f.followee_id = p.user_id
    where p.activity_id like 'seed_%_1' and f.follower_id::text like 'a0000000-%'
      and not exists (select 1 from public.comments c where c.activity_user_id = p.user_id and c.activity_id = p.activity_id and c.user_id = f.follower_id);
  end if;
end $$;
